13	/// Every route this story's app shell resolves (Boundaries: "Routes:
14	/// `/boot`, `/auth`, `/reauth`, `/`, `/meus-registros`, `/planos-de-acao`,
15	/// `/configuracoes`"). Named constants so no call site retypes a path
16	/// literal that could drift from the one `GoRouter` below.
17	abstract final class AppRoutePaths {
18	  static const boot = '/boot';
19	  static const auth = '/auth';
20	  static const reauth = '/reauth';
21	  static const home = '/';
22	  static const meusRegistros = '/meus-registros';
23	  static const planosDeAcao = '/planos-de-acao';
24	  static const configuracoes = '/configuracoes';
25	}
26	
27	/// The epic's ONE `GoRouter`/`redirect` (Boundaries: "never a second
28	/// competing `redirect`") — composes only [SessionRepository.currentStatus]
29	/// for now. [sessionRepository] is taken as a parameter (rather than this
30	/// file reaching into `sl` itself) purely so a test can pass a fake/mock one
31	/// directly, without touching the global DI container.
32	///
33	/// [navigatorKey] is accepted explicitly (rather than letting `GoRouter`
34	/// generate its own internally) so the caller — `main.dart`'s
35	/// `ExpiryOverlayHost` — can reach the Navigator's own `BuildContext`
36	/// through the same, public, documented key instead of reaching into
37	/// `GoRouter`'s internal `routerDelegate` (not part of its public API).
38	GoRouter buildAppRouter({
39	  required SessionRepository sessionRepository,
40	  required GlobalKey<NavigatorState> navigatorKey,
41	}) {
42	  return GoRouter(
43	    navigatorKey: navigatorKey,
44	    initialLocation: AppRoutePaths.boot,
45	    refreshListenable: _GoRouterRefreshStream(sessionRepository.statusStream),
46	    redirect: (context, state) => _redirect(sessionRepository, state),
47	    routes: [
48	      GoRoute(
49	        path: AppRoutePaths.boot,
50	        builder: (context, state) => const BootSplashScreen(),
51	      ),
52	      GoRoute(
53	        path: AppRoutePaths.auth,
54	        builder: (context, state) => AuthScreen(
55	          cubit: sl<AuthCubit>(),
56	          onAuthenticated: (context) => context.go(AppRoutePaths.home),
57	        ),
58	      ),
59	      GoRoute(
60	        path: AppRoutePaths.reauth,
61	        builder: (context, state) => const BiometricReauthPlaceholderScreen(),
62	      ),
63	      GoRoute(
64	        path: AppRoutePaths.home,
65	        builder: (context, state) => const HomeChatPlaceholderScreen(),
66	      ),
67	      GoRoute(
68	        path: AppRoutePaths.meusRegistros,
69	        builder: (context, state) => const MeusRegistrosPlaceholderScreen(),
70	      ),
71	      GoRoute(
72	        path: AppRoutePaths.planosDeAcao,
73	        builder: (context, state) => const ActionPlansPlaceholderScreen(),
74	      ),
75	      GoRoute(
76	        path: AppRoutePaths.configuracoes,
77	        builder: (context, state) => const ConfiguracoesPlaceholderScreen(),
78	      ),
79	    ],
80	  );
81	}
82	
83	/// I/O & Edge-Case Matrix:
84	/// - status not yet known (`null`) -> `/boot`, unless already there.
85	/// - `unauthenticated` -> `/auth`, unless already there.
86	/// - `authenticated`/`expired` -> leaves `/boot`/`/auth` for `/`; every
87	///   other location is left alone *except* `/reauth` while already
88	///   `authenticated` (bounced home below — `/reauth` is meant to be
89	///   reached only by the expiry overlay's own explicit navigation while
90	///   `expired`, code review Story 1.6) — a mid-session expiry never
91	///   navigates away (Story 1.5 behavior preserved), and the three
92	///   non-Home destinations stay reachable while `expired`.
93	///
94	/// AD-14 seam: Epic 2 (RF03) plugs a local `VaultStatus` gate in here,
95	/// checked *before* this session check (Cross-Story Dependencies: "vault
96	/// checked first") — e.g. `if (vaultStatus == VaultStatus.locked) return
97	/// AppRoutePaths.vaultLock;` ahead of the block below. Nothing here should
98	/// assume session validity alone ever decides access once that lands.
99	String? _redirect(SessionRepository sessionRepository, GoRouterState state) {
100	  final status = sessionRepository.currentStatus;
101	  final location = state.matchedLocation;
102	
103	  if (status == null) {
104	    return location == AppRoutePaths.boot ? null : AppRoutePaths.boot;
105	  }
106	
107	  if (status == SessionStatus.unauthenticated) {
108	    return location == AppRoutePaths.auth ? null : AppRoutePaths.auth;
109	  }
110	
111	  // status is authenticated or expired.
112	  if (location == AppRoutePaths.boot || location == AppRoutePaths.auth) {
113	    return AppRoutePaths.home;
114	  }
115	  // `/reauth` is a throwaway placeholder standing in for Epic 2's real
116	  // reauth flow; it should never be sitting open once the session is back
117	  // to fully `authenticated` (code review, Story 1.6).
118	  if (location == AppRoutePaths.reauth &&
119	      status == SessionStatus.authenticated) {
120	    return AppRoutePaths.home;
121	  }
122	  return null;
123	}
124	
125	/// Wraps [stream] as a `Listenable` so `GoRouter`'s `refreshListenable` can
126	/// re-run [_redirect] on every emission — go_router 18.1.1 exports no
127	/// `GoRouterRefreshStream` of its own (Code Map), so this is that small
128	/// local class.
129	class _GoRouterRefreshStream extends ChangeNotifier {
130	  _GoRouterRefreshStream(Stream<dynamic> stream) {
131	    _subscription = stream.listen(
132	      (_) => notifyListeners(),
133	      // Mirrors `ExpiryOverlayHost`'s and `SessionRepositoryImpl`'s own
134	      // subscriptions to this same stream — no current implementation
135	      // ever errors on it, but a future one that did must not surface as
136	      // an unhandled zone exception here specifically.
137	      onError: (_, _) {},
138	    );
139	  }
140	
141	  late final StreamSubscription<dynamic> _subscription;
142	
143	  @override
144	  void dispose() {
145	    _subscription.cancel();
146	    super.dispose();
147	  }
148	}
